 if(state.bands){for(const g of H.governments){const start=Math.max(state.start,C.yearFraction(g.start)),end=Math.min(state.end+1,C.yearFraction(g.end||ASOF));if(end<=start)continue;const color=H.parties[g.party].color;content+=`<rect x="${x(start)}" y="${T}" width="${x(end)-x(start)}" height="${B-T}" fill="${color}" opacity=".055"/><rect x="${x(start)}" y="${B+35}" width="${Math.max(.5,x(end)-x(start))}" height="7" fill="${color}"><title>${esc(label(g.name)+' · '+g.start+' → '+(g.end||t('ongoing'))+' · '+label(g.coalition))}</title></rect>`;}}
